namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple, classic pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Rice"],
                Steps = [
                    "Marinate chicken pieces in yogurt, garam masala, and salt for at least 1 hour.",
                    "Grill or broil chicken until lightly charred, then set aside.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add cumin and garam masala, cook for 1 minute until fragrant.",
                    "Pour in tomato sauce and simmer for 15 minutes.",
                    "Stir in heavy cream and add the chicken. Simmer 10 minutes.",
                    "Serve over basmati rice."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Rich and creamy pasta with pancetta and egg.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente. Reserve 1 cup pasta water.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Parmesan and plenty of black pepper.",
                    "Drain pasta and toss with pancetta off the heat.",
                    "Pour egg mixture over pasta, tossing quickly to create a creamy sauce.",
                    "Add pasta water a splash at a time to reach desired consistency."
                ],
                Ratings = [4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Lime"],
                Steps = [
                    "Brown ground beef in a skillet, breaking it into crumbles.",
                    "Add taco seasoning and a splash of water. Simmer 5 minutes.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, and sour cream.",
                    "Squeeze lime juice over the top and serve."
                ],
                Ratings = [4, 4, 3, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix fish sauce, tamarind paste, and sugar to make the sauce.",
                    "Stir-fry shrimp in oil until pink, then push to one side.",
                    "Scramble eggs in the same pan.",
                    "Add noodles and sauce, toss everything together over high heat.",
                    "Add bean sprouts and green onions, toss briefly.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                Ratings = [5, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh, chunky avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit the avocados. Scoop flesh into a bowl.",
                    "Mash with a fork to desired chunkiness.",
                    "Stir in lime juice, diced onion, minced jalapeño, and chopped cilantro.",
                    "Fold in diced tomato and season with salt.",
                    "Serve immediately with tortilla chips."
                ],
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 7, Title = "Green Curry", Category = "Thai",
                Description = "Aromatic coconut curry with vegetables and chicken.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken thighs", "Bamboo shoots", "Thai basil", "Bell pepper", "Fish sauce", "Sugar", "Jasmine rice"],
                Steps = [
                    "Heat a splash of coconut cream in a pot until it separates.",
                    "Fry green curry paste in the cream for 2 minutes until fragrant.",
                    "Add sliced chicken and cook until no longer pink.",
                    "Pour in the rest of the coconut milk and bring to a simmer.",
                    "Add bamboo shoots, sliced bell pepper, fish sauce, and sugar.",
                    "Simmer 15 minutes until chicken is cooked through.",
                    "Stir in Thai basil and serve over jasmine rice."
                ],
                Ratings = [4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Crispy edges, chewy centers, loaded with chocolate chips.",
                Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "All-purpose flour", "Baking soda", "Salt", "Chocolate chips"],
                Steps = [
                    "Cream butter with both sugars until light and fluffy.",
                    "Beat in eggs one at a time, then add vanilla.",
                    "Whisk together flour, baking soda, and salt in a separate bowl.",
                    "Gradually mix dry ingredients into the wet mixture.",
                    "Fold in chocolate chips.",
                    "Scoop rounded tablespoons onto parchment-lined baking sheets.",
                    "Bake at 375°F (190°C) for 9–11 minutes until edges are golden.",
                    "Cool on the sheet for 5 minutes before transferring to a rack."
                ],
                Ratings = [5, 5, 5, 5, 4]
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating d-inline-flex align-items-center gap-2">
    <div class="stars" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link p-0 fs-4 text-decoration-none @(star <= _selectedRating ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    aria-label="@star stars"
                    disabled="@_hasRated">
                @(star <= _selectedRating ? "★" : "☆")
            </button>
        }
    </div>
    @if (_hasRated)
    {
        <span class="text-success small">Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted small">Click to rate</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentAverage { get; set; }

    [Parameter]
    public int TotalRatings { get; set; }

    private int _selectedRating;
    private bool _hasRated;

    private void SubmitRating(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        Recipes.AddRating(RecipeId, stars);

        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.Ratings.Count;
        }
    }
}

