        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))
            return;

        _isSubmitting = true;

        var ingredients = _ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = _stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = Recipes.AddRecipe(_title, _category, _description, ingredients, steps);
        _submittedId = recipe.Id;
        _submitted = true;
        _isSubmitting = false;
    }

