@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService Recipes

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The requested recipe does not exist.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <div class="mb-4">
        <span class="text-warning fs-5 me-2">
            ★ @(_recipe.AverageRating > 0 ? _recipe.AverageRating.ToString() : "—")
        </span>
        <span class="text-muted">(@_recipe.Ratings.Count rating@(_recipe.Ratings.Count != 1 ? "s" : ""))</span>
    </div>

    <div class="mb-4 p-3 border rounded bg-light">
        <strong>Rate this recipe:</strong>
        <StarRating RecipeId="@_recipe.Id"
                    CurrentAverage="@_recipe.AverageRating"
                    TotalRatings="@_recipe.Ratings.Count" />
    </div>

    <div class="row">
        <div class="col-md-4 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in _recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = Recipes.GetById(Id);
    }
}

