@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

@if (_recipes.Count == 0)
{
    <h1>Category Not Found</h1>
    <p>No recipes found for "@CategoryName".</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <p class="text-muted mb-4">@_recipes.Count recipe@(_recipes.Count != 1 ? "s" : "") in this category.</p>

    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in _recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                            <span class="text-warning">
                                @(recipe.AverageRating > 0 ? $"★ {recipe.AverageRating} ({recipe.Ratings.Count})" : "No ratings yet")
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="mt-4">
        <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
    </div>
}

